// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

/**
 * Per-thread count of planning-time reads that a wall-clock limit cut short. A planner input whose result depends on
 * how far a timed read got before its limit fired is not reproducible, even when no planning revision moved, so a
 * planning that observed such a cut is retained by no plan cache: neither the pipeline cache nor, through its cost
 * sessions reporting themselves not reproducible ({@link LmdbPlanningCutAwareCostSession}), the packed plan cache, nor
 * the decision cache as a detached refresh. The planning itself is not degraded: its request executes it as planned.
 *
 * <p>
 * A planning scope marks where one planning began on the thread; nested scopes join the outermost, so a session opened
 * inside a pipeline planning compares against the start of that whole planning.
 *
 * <p>
 * The state is thread-confined: it is written and read only by the planning thread that performed the timed read, and
 * nothing is allocated after the thread's first use.
 */
final class LmdbPlanningWallClockCuts {

	/** Cuts recorded on this thread, open planning scopes, and the cut count when the outermost scope opened. */
	private static final ThreadLocal<long[]> STATE = ThreadLocal.withInitial(() -> new long[3]);

	private LmdbPlanningWallClockCuts() {
	}

	/** Records that a planning-time read on this thread ended because its wall-clock limit was reached. */
	static void recordCut() {
		STATE.get()[0]++;
		// A read cut short answers what its time budget allowed, not what the learned state holds: no replay of the
		// planning's reads can stand for it (no cache retains such a planning either).
		LmdbPlanningReadLog.markIncomplete("wall-clock-cut");
	}

	/** Monotonic count of cuts on this thread; compare two readings to learn whether a cut happened in between. */
	static long count() {
		return STATE.get()[0];
	}

	/**
	 * Opens a planning scope on this thread; always pair it with {@link #endPlanning()} in a finally block. The
	 * planning's learned-state read log ({@link LmdbPlanningReadLog}) shares the scope.
	 */
	static void beginPlanning() {
		long[] state = STATE.get();
		if (state[1]++ == 0L) {
			state[2] = state[0];
		}
		LmdbPlanningReadLog.beginPlanning();
	}

	/** Closes the innermost planning scope this thread opened. */
	static void endPlanning() {
		long[] state = STATE.get();
		if (state[1] > 0L) {
			state[1]--;
		}
		LmdbPlanningReadLog.endPlanning();
	}

	/**
	 * The cut count a planning that starts now compares against: the outermost open scope's mark when a scope is open,
	 * otherwise the current count.
	 */
	static long planningMark() {
		long[] state = STATE.get();
		return state[1] > 0L ? state[2] : state[0];
	}
}
